New-AzNetworkInterface -Name 'avd-lab-01-nic' -ResourceGroupName 'sample-resourcegroupname' -Location 'eastus2' -SubnetId ((Get-AzVirtualNetwork -Name 'sample-vnetname' -ResourceGroupName 'sample-resourcegroupname').Subnets | Where-Object Name -eq 'snet-hosts').Id
New-AzVM -ResourceGroupName 'sample-resourcegroupname' -Location 'eastus2' -VM (New-AzVMConfig -VMName 'avd-lab-01' -VMSize 'Standard_D4s_v5' -SecurityType 'TrustedLaunch' -IdentityType SystemAssigned -LicenseType 'Windows_Client' | Set-AzVMOperatingSystem -Windows -ComputerName 'avd-lab-01' -Credential (Get-Credential -Message 'Local administrator for the VM') -ProvisionVMAgent | Set-AzVMSourceImage -PublisherName 'MicrosoftWindowsDesktop' -Offer 'office-365' -Skus 'win11-24h2-avd-m365' -Version 'latest' | Add-AzVMNetworkInterface -Id (Get-AzNetworkInterface -Name 'avd-lab-01-nic' -ResourceGroupName 'sample-resourcegroupname').Id | Set-AzVMBootDiagnostic -Disable)
Set-AzVMExtension -ResourceGroupName 'sample-resourcegroupname' -VMName 'avd-lab-01' -Location 'eastus2' -Name 'AADLoginForWindows' -Publisher 'Microsoft.Azure.ActiveDirectory' -ExtensionType 'AADLoginForWindows' -TypeHandlerVersion '2.0'
Set-AzVMExtension -ResourceGroupName 'sample-resourcegroupname' -VMName 'avd-lab-01' -Location 'eastus2' -Name 'AvdAgentDsc' -Publisher 'Microsoft.Powershell' -ExtensionType 'DSC' -TypeHandlerVersion '2.73' -Settings @{ modulesUrl = 'https://wvdportalstorageblob.blob.core.windows.net/galleryartifacts/Configuration.zip'; configurationFunction = 'Configuration.ps1\AddSessionHost'; properties = @{ hostPoolName = 'sample-hostpoolname'; aadJoin = $true } } -ProtectedSettings @{ properties = @{ registrationInfoToken = (Read-Host -Prompt 'Host pool registration token (from the previous task)') } }
New-AzRoleAssignment -ObjectId 'sample-groupobjectid' -RoleDefinitionName 'Virtual Machine User Login' -Scope (Get-AzVM -Name 'avd-lab-01' -ResourceGroupName 'sample-resourcegroupname').Id
